using HostedWorkQueue;using Xunit;public sealed class QueueTests{[Fact]public async Task Worker_drains_completed_queue(){var q=new WorkQueue(2);var seen=new List<Guid>();var w=new QueueWorker(q,(i,_)=>{seen.Add(i.Id);return ValueTask.CompletedTask;});var id=Guid.NewGuid();await q.EnqueueAsync(new(id,"x"));q.Complete();await w.RunAsync(default);Assert.Equal(id,Assert.Single(seen));}[Fact]public async Task Item_failure_does_not_stop_next_item(){var q=new WorkQueue(2);var seen=new List<string>();var w=new QueueWorker(q,(i,_)=>{if(i.Payload=="bad")throw new InvalidOperationException();seen.Add(i.Payload);return ValueTask.CompletedTask;});await q.EnqueueAsync(new(Guid.NewGuid(),"bad"));await q.EnqueueAsync(new(Guid.NewGuid(),"good"));q.Complete();await w.RunAsync(default);Assert.Equal(["good"],seen);Assert.Equal(1,w.Failures);}[Fact]public async Task Cancellation_stops_worker(){var q=new WorkQueue(1);using var cts=new CancellationTokenSource();cts.Cancel();await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>new QueueWorker(q,(_,_)=>ValueTask.CompletedTask).RunAsync(cts.Token));}[Fact]public async Task Capacity_applies_backpressure(){var q=new WorkQueue(1);await q.EnqueueAsync(new(Guid.NewGuid(),"first"));using var cts=new CancellationTokenSource(TimeSpan.FromMilliseconds(50));await Assert.ThrowsAnyAsync<OperationCanceledException>(async()=>await q.EnqueueAsync(new(Guid.NewGuid(),"second"),cts.Token));}}
